BEGIN READ ONLY; SELECT a."Id" AS asset_id,c."Slug",a."CompanyId",a."SerialNumber",a."Status",cat."CompanyId"=a."CompanyId" AS category_scoped,e."CompanyId"=a."CompanyId" AS employee_scoped,e."EmployeeNumber" FROM "Assets" a JOIN "Companies" c ON c."Id"=a."CompanyId" JOIN "AssetCategories" cat ON cat."Id"=a."CategoryId" LEFT JOIN "Employees" e ON e."Id"=a."AssignedEmployeeId" WHERE a."AssetTag"='SANTA-KABUL-20261025-01'; SELECT ev."EventType",ev."CompanyId"=a."CompanyId" AS event_scoped FROM "AssetEvents" ev JOIN "Assets" a ON a."Id"=ev."AssetId" WHERE a."AssetTag"='SANTA-KABUL-20261025-01' ORDER BY ev."OccurredAt"; COMMIT;
